# Plan-and-execute with re-planning and tool-result clearing, on top of native tool calling.
import json
from typing import Callable

from openai import OpenAI

client = OpenAI()
MODEL = "agent-model-id"
KEEP_RECENT_RESULTS = 4          # older tool results are replaced by stubs to keep the context small


def clear_old_results(messages: list[dict]) -> None:
    tool_idx = [i for i, m in enumerate(messages) if m["role"] == "tool"]
    for i in tool_idx[:-KEEP_RECENT_RESULTS]:
        if not messages[i]["content"].startswith("[elided"):
            messages[i]["content"] = f"[elided: {len(messages[i]['content'])} chars, re-run the tool if needed]"


def make_plan(task: str) -> list[str]:
    res = client.chat.completions.create(
        model=MODEL, temperature=0, response_format={"type": "json_object"},
        messages=[{"role": "system", "content": 'Break the task into 3-7 concrete, checkable steps. JSON: {"steps": [str]}'},
                  {"role": "user", "content": task}],
    )
    return json.loads(res.choices[0].message.content or "{}").get("steps", [task])


def execute(task: str, tools: dict[str, Callable[..., str]], specs: list[dict], max_steps: int = 30) -> dict:
    plan = make_plan(task)
    messages = [
        {"role": "system", "content": "Work through the plan step by step. Verify each step with a tool before "
                                      "moving on. If an observation invalidates the plan, say REPLAN and why."},
        {"role": "user", "content": f"Task: {task}\nPlan:\n" + "\n".join(f"{i + 1}. {s}" for i, s in enumerate(plan))},
    ]
    for step in range(max_steps):
        clear_old_results(messages)
        msg = client.chat.completions.create(model=MODEL, messages=messages, tools=specs).choices[0].message
        messages.append(msg.model_dump(exclude_none=True))
        if not msg.tool_calls:
            if msg.content and "REPLAN" in msg.content:
                plan = make_plan(f"{task}\nWhat we learned so far: {msg.content}")
                messages.append({"role": "user", "content": "New plan:\n" + "\n".join(plan)})
                continue
            return {"status": "done", "answer": msg.content, "steps": step + 1, "plan": plan}
        for call in msg.tool_calls:
            fn = tools.get(call.function.name)
            try:
                result = fn(**json.loads(call.function.arguments)) if fn else f"unknown tool {call.function.name}"
            except Exception as e:                       # errors go back to the model as observations
                result = f"error: {e}"
            messages.append({"role": "tool", "tool_call_id": call.id, "content": str(result)[:6000]})
    return {"status": "max_steps", "steps": max_steps, "plan": plan}

// A bounded agent loop: finish tool, step/token/time budgets, repeat detection, approvals and cancellation.
import Anthropic from "@anthropic-ai/sdk";
import { createHash } from "node:crypto";
import { z } from "zod";

const anthropic = new Anthropic();
const MODEL = process.env.AGENT_MODEL!;

type ToolDef = {
  schema: z.ZodTypeAny;
  description: string;
  inputSchema: Anthropic.Tool["input_schema"];
  sideEffect: boolean;
  run: (input: unknown, ctx: { signal: AbortSignal; idempotencyKey: string }) => Promise<string>;
};

const Finish = z.object({ status: z.enum(["success", "blocked", "needs_input"]), summary: z.string().max(2000) });

export type Budget = { maxSteps: number; maxInputTokens: number; deadlineMs: number };
export type RunResult = z.infer<typeof Finish> & { stopReason: string; steps: number; inputTokens: number };

export async function runAgent(
  runId: string,
  task: string,
  tools: Record<string, ToolDef>,
  budget: Budget,
  approve: (name: string, input: unknown) => Promise<boolean>,
  signal: AbortSignal,
): Promise<RunResult> {
  const toolSpecs: Anthropic.Tool[] = [
    ...Object.entries(tools).map(([name, t]) => ({ name, description: t.description, input_schema: t.inputSchema })),
    {
      name: "finish",
      description: "Call when the task is complete, blocked, or needs user input. Verify before claiming success.",
      input_schema: {
        type: "object",
        properties: { status: { type: "string", enum: ["success", "blocked", "needs_input"] }, summary: { type: "string" } },
        required: ["status", "summary"],
      },
    },
  ];
  const messages: Anthropic.MessageParam[] = [{ role: "user", content: task }];
  const seen = new Map<string, number>();
  const started = Date.now();
  let inputTokens = 0;

  for (let step = 1; step <= budget.maxSteps; step++) {
    if (signal.aborted) return stop("cancelled", step);
    if (Date.now() - started > budget.deadlineMs) return stop("timeout", step);
    if (inputTokens > budget.maxInputTokens) return stop("token_budget", step);

    const res = await anthropic.messages.create(
      { model: MODEL, max_tokens: 4096, system: "You are a careful operations agent.", tools: toolSpecs, messages },
      { signal },
    );
    inputTokens += res.usage.input_tokens + (res.usage.cache_read_input_tokens ?? 0);
    messages.push({ role: "assistant", content: res.content });

    const calls = res.content.filter((b): b is Anthropic.ToolUseBlock => b.type === "tool_use");
    if (calls.length === 0) return { status: "needs_input", summary: textOf(res), stopReason: "no_tool_call", steps: step, inputTokens };

    const results: Anthropic.ToolResultBlockParam[] = [];
    for (const call of calls) {
      if (call.name === "finish") {
        const parsed = Finish.safeParse(call.input);
        if (parsed.success) return { ...parsed.data, stopReason: "finish", steps: step, inputTokens };
        results.push({ type: "tool_result", tool_use_id: call.id, is_error: true, content: parsed.error.message });
        continue;
      }
      results.push({ type: "tool_result", tool_use_id: call.id, ...(await execute(call)) });
    }
    const next: Anthropic.ContentBlockParam[] = [...results]; // exactly one result per tool_use id
    if (step >= budget.maxSteps - 2 || inputTokens > budget.maxInputTokens * 0.8) {
      next.push({ type: "text", text: "Budget nearly spent. Wrap up now and call finish with an honest status." });
    }
    messages.push({ role: "user", content: next });
  }
  return stop("max_steps", budget.maxSteps);

  async function execute(call: Anthropic.ToolUseBlock): Promise<{ content: string; is_error?: boolean }> {
    const tool = tools[call.name];
    if (!tool) return { content: `Unknown tool ${call.name}`, is_error: true };
    const input = tool.schema.safeParse(call.input);
    if (!input.success) return { content: `Invalid arguments: ${input.error.message}`, is_error: true };

    const key = createHash("sha256").update(call.name + JSON.stringify(input.data)).digest("hex");
    const repeats = (seen.get(key) ?? 0) + 1;
    seen.set(key, repeats);
    if (repeats >= 3) return { content: "You already made this exact call twice. Change approach or finish.", is_error: true };

    if (tool.sideEffect && !(await approve(call.name, input.data))) return { content: "Rejected by the user.", is_error: true };
    try {
      const out = await tool.run(input.data, { signal: AbortSignal.any([signal, AbortSignal.timeout(30_000)]), idempotencyKey: `${runId}:${call.id}` });
      return { content: out.length > 8000 ? `${out.slice(0, 8000)}\n[truncated, ${out.length} chars total]` : out };
    } catch (err) {
      return { content: `Tool failed: ${(err as Error).message}`, is_error: true };
    }
  }

  function stop(stopReason: string, steps: number): RunResult {
    return { status: "blocked", summary: `Stopped (${stopReason}) after ${steps} steps.`, stopReason, steps, inputTokens };
  }
}

const textOf = (m: Anthropic.Message) => m.content.flatMap((b) => (b.type === "text" ? [b.text] : [])).join("\n");

# Function calling with strict schemas, parallel read-only calls, server-side validation and teaching errors.
import json
from concurrent.futures import ThreadPoolExecutor

from openai import OpenAI
from pydantic import BaseModel, Field, ValidationError

client = OpenAI()
MODEL = "tool-model-id"


class SearchOrders(BaseModel):
    customer_email: str = Field(description="Exact customer email")
    status: str | None = Field(description="One of: open, shipped, refunded; null for any")
    limit: int = Field(ge=1, le=20)


TOOLS = [{
    "type": "function",
    "function": {
        "name": "search_orders",
        "description": "Find a customer's recent orders. Use before answering any question about an order. "
                       "Returns at most `limit` orders, newest first, with id, date, status and total.",
        "strict": True,                                   # arguments always match the schema
        "parameters": {
            "type": "object",
            "properties": {
                "customer_email": {"type": "string", "description": "Exact customer email"},
                "status": {"type": ["string", "null"], "enum": ["open", "shipped", "refunded", None]},
                "limit": {"type": "integer", "description": "1-20"},
            },
            "required": ["customer_email", "status", "limit"],   # strict mode: all listed, optional = nullable
            "additionalProperties": False,
        },
    },
}]


def search_orders(args: SearchOrders, caller_email: str) -> str:
    if args.customer_email.lower() != caller_email.lower():   # schema-valid is not authorised
        return "error: you can only look up orders for the signed-in customer"
    rows = [{"id": "ORD-104233", "date": "2026-09-28", "status": "shipped", "total": "49.00 EUR"}]
    return json.dumps({"orders": rows[: args.limit], "note": f"showing {len(rows)} of {len(rows)}"})


def run_call(call, caller_email: str) -> dict:
    try:
        args = SearchOrders.model_validate_json(call.function.arguments)
        out = search_orders(args, caller_email) if call.function.name == "search_orders" else "error: unknown tool"
    except ValidationError as e:
        out = f"error: invalid arguments, fix and retry: {e.errors()[0]['msg']}"
    return {"role": "tool", "tool_call_id": call.id, "content": out}


def chat(question: str, caller_email: str) -> str:
    messages = [{"role": "system", "content": "You are a support assistant. Use tools; never guess order data."},
                {"role": "user", "content": question}]
    for _ in range(6):
        msg = client.chat.completions.create(model=MODEL, messages=messages, tools=TOOLS).choices[0].message
        messages.append(msg.model_dump(exclude_none=True))
        if not msg.tool_calls:
            return msg.content or ""
        with ThreadPoolExecutor(max_workers=4) as pool:          # read-only tools: safe to run in parallel
            messages.extend(pool.map(lambda c: run_call(c, caller_email), msg.tool_calls))
    return "Sorry, I could not complete this request."

// A small MCP server with the official TypeScript SDK: agent-friendly tools, structured output, teaching errors.
import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";
import { z } from "zod";
import { searchTickets, getTicket } from "./tickets-db.js"; // your data access layer

const server = new McpServer({ name: "tickets", version: "0.9.0" });

server.registerTool(
  "search_tickets",
  {
    title: "Search support tickets",
    description:
      "Full-text search over support tickets, newest first. Use to find prior incidents or similar reports. " +
      "Do not use to fetch one known ticket (use get_ticket).",
    inputSchema: {
      query: z.string().min(2).describe("Keywords, error codes or product names"),
      status: z.enum(["open", "closed", "any"]).default("any"),
      limit: z.number().int().min(1).max(20).default(10),
    },
    outputSchema: {
      tickets: z.array(z.object({ id: z.string(), title: z.string(), status: z.string(), updatedAt: z.string() })),
      total: z.number(),
    },
  },
  async ({ query, status, limit }) => {
    const { rows, total } = await searchTickets(query, status, limit);
    const structured = { tickets: rows.map(({ id, title, status, updatedAt }) => ({ id, title, status, updatedAt })), total };
    const hint = total > rows.length ? ` Showing ${rows.length} of ${total}; add keywords or a status filter.` : "";
    return {
      content: [{ type: "text", text: JSON.stringify(structured) + hint }],
      structuredContent: structured,
    };
  },
);

server.registerTool(
  "get_ticket",
  {
    title: "Get one ticket",
    description: "Fetch a ticket's full thread by id (format T-123). Long threads are truncated to the last 20 messages.",
    inputSchema: { id: z.string().describe("Ticket id like T-881") },
  },
  async ({ id }) => {
    if (!/^T-\d+$/.test(id)) {
      return { isError: true, content: [{ type: "text", text: `Invalid id "${id}". Ticket ids look like T-881.` }] };
    }
    const ticket = await getTicket(id);
    if (!ticket) return { isError: true, content: [{ type: "text", text: `No ticket ${id}. Try search_tickets.` }] };
    return { content: [{ type: "text", text: JSON.stringify({ ...ticket, messages: ticket.messages.slice(-20) }) }] };
  },
);

// stdout is the protocol channel for stdio servers: log to stderr only.
console.error("tickets MCP server starting");
await server.connect(new StdioServerTransport());

# The same idea in Python with FastMCP from the official SDK, served over Streamable HTTP.
# pip install "mcp[cli]"
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("runbooks")

RUNBOOKS = {
    "db-failover": "1. Confirm primary is down via health endpoint...\n2. Promote replica...",
    "cache-stampede": "1. Enable request coalescing...\n2. Add jittered TTLs...",
}


@mcp.tool()
def list_runbooks() -> list[str]:
    """List available incident runbook names. Call before get_runbook if unsure of the name."""
    return sorted(RUNBOOKS)


@mcp.tool()
def get_runbook(name: str) -> str:
    """Return the steps of one incident runbook by exact name (see list_runbooks)."""
    if name not in RUNBOOKS:
        close = [n for n in RUNBOOKS if name.split("-")[0] in n]
        raise ValueError(f"No runbook '{name}'. Closest: {close or sorted(RUNBOOKS)}")  # becomes isError result
    return RUNBOOKS[name]


@mcp.resource("runbook://{name}")
def runbook_resource(name: str) -> str:
    """Runbooks as resources, so a host can attach one as context by URI."""
    return RUNBOOKS.get(name, "")


if __name__ == "__main__":
    # Behind a reverse proxy with OAuth in production; never expose an unauthenticated server publicly.
    mcp.run(transport="streamable-http")

// Host-side tool policy: per-server permissions, definition pinning (rug-pull detection), egress allowlist,
// and outbound-argument checks before any tool executes.
import { createHash } from "node:crypto";

type ToolDef = { server: string; name: string; description: string; inputSchema: unknown };
type Policy = { mode: "auto" | "approve" | "deny"; egressHosts?: string[] };

const POLICIES: Record<string, Policy> = {
  "docs/search": { mode: "auto" },
  "web/fetch": { mode: "auto", egressHosts: ["docs.python.org", "developer.mozilla.org"] },
  "mail/send_email": { mode: "approve" },
  "shell/exec": { mode: "deny" },
};

const pinned = new Map<string, string>(); // tool key -> hash of the definition the user approved

const keyOf = (t: ToolDef) => `${t.server}/${t.name}`;
const hashOf = (t: ToolDef) => createHash("sha256").update(JSON.stringify([t.description, t.inputSchema])).digest("hex");

export function reviewToolList(tools: ToolDef[]): { changed: string[]; collisions: string[] } {
  const changed = tools.filter((t) => pinned.has(keyOf(t)) && pinned.get(keyOf(t)) !== hashOf(t)).map(keyOf);
  const byName = new Map<string, string[]>();
  for (const t of tools) byName.set(t.name, [...(byName.get(t.name) ?? []), t.server]);
  const collisions = [...byName].filter(([, servers]) => servers.length > 1).map(([n, s]) => `${n}: ${s.join(", ")}`);
  return { changed, collisions }; // changed definitions must be re-approved by the user before use
}

export function approveDefinition(t: ToolDef) {
  pinned.set(keyOf(t), hashOf(t));
}

const SECRET_PATTERNS = [/sk-[A-Za-z0-9]{20,}/, /-----BEGIN [A-Z ]*PRIVATE KEY-----/, /AKIA[0-9A-Z]{16}/];

export type Decision = { action: "run" | "ask_user" | "block"; reason?: string };

export function decide(t: ToolDef, args: Record<string, unknown>): Decision {
  if (!pinned.has(keyOf(t)) || pinned.get(keyOf(t)) !== hashOf(t)) return { action: "block", reason: "definition not approved" };
  const policy = POLICIES[keyOf(t)] ?? { mode: "approve" }; // unknown tools default to approval, not auto
  if (policy.mode === "deny") return { action: "block", reason: "tool disabled by policy" };

  const serialized = JSON.stringify(args);
  if (SECRET_PATTERNS.some((re) => re.test(serialized))) return { action: "block", reason: "secret-like value in arguments" };

  if (policy.egressHosts) {
    const url = typeof args.url === "string" ? safeUrl(args.url) : null;
    if (!url || url.protocol !== "https:" || !policy.egressHosts.includes(url.hostname)) {
      return { action: "block", reason: "destination not on the egress allowlist" };
    }
    if (url.search.length > 200) return { action: "ask_user", reason: "long query string could carry data out" };
  }
  return policy.mode === "auto" ? { action: "run" } : { action: "ask_user", reason: "side effect requires approval" };
}

function safeUrl(s: string): URL | null {
  try {
    return new URL(s);
  } catch {
    return null;
  }
}

// Orchestrator-worker with explicit delegation briefs, parallel workers, caps and structured results.
import { generateObject, generateText, stepCountIs, type ToolSet } from "ai";
import { z } from "zod";

const LEAD_MODEL = process.env.LEAD_MODEL!;     // provider/model strings resolved by your AI SDK setup
const WORKER_MODEL = process.env.WORKER_MODEL!;
const MAX_WORKERS = 5;

const Brief = z.object({
  objective: z.string(),
  outputFormat: z.string(),
  sources: z.array(z.string()).describe("Which tools or sources to use"),
  outOfScope: z.string().describe("What other workers cover; do not duplicate"),
  maxSteps: z.number().int().min(2).max(12),
});
const Plan = z.object({ complexity: z.enum(["simple", "moderate", "broad"]), briefs: z.array(Brief).min(1).max(MAX_WORKERS) });
const Finding = z.object({ claims: z.array(z.object({ text: z.string(), source: z.string() })), confidence: z.enum(["low", "medium", "high"]), gaps: z.string() });

export async function research(question: string, tools: ToolSet) {
  const { object: plan } = await generateObject({
    model: LEAD_MODEL,
    schema: Plan,
    system:
      "You are a research lead. Simple fact: 1 worker. Comparison: 2-4 workers. Broad survey: up to 5. " +
      "Give each worker a distinct objective, an output format, sources to use and explicit boundaries.",
    prompt: question,
  });

  const settled = await Promise.allSettled(
    plan.briefs.map(async (b) => {
      const run = await generateText({
        model: WORKER_MODEL,
        tools,
        stopWhen: stepCountIs(b.maxSteps),             // per-worker step cap enforced by the SDK loop
        system: `Objective: ${b.objective}\nUse: ${b.sources.join(", ")}\nOut of scope: ${b.outOfScope}`,
        prompt: `Research the objective. Finish with findings in this format: ${b.outputFormat}`,
        abortSignal: AbortSignal.timeout(90_000),
      });
      // Condense to a structured finding so the lead never sees the worker's raw transcript.
      const { object } = await generateObject({ model: WORKER_MODEL, schema: Finding, prompt: run.text });
      return { brief: b.objective, ...object, tokens: run.totalUsage.totalTokens };
    }),
  );

  const findings = settled.flatMap((s) => (s.status === "fulfilled" ? [s.value] : []));
  const failed = settled.length - findings.length;

  const { text } = await generateText({
    model: LEAD_MODEL,
    system: "Synthesise the findings. Cite sources. Flag contradictions and gaps instead of hiding them.",
    prompt: JSON.stringify({ question, findings: findings.map(({ tokens: _t, ...f }) => f), failedWorkers: failed }),
  });
  return { answer: text, workers: findings.length, failed, tokens: findings.reduce((s, f) => s + (f.tokens ?? 0), 0) };
}
